import numpy as np
from scipy import stats
from sklearn.feature_selection import mutual_info_classif
from sklearn.preprocessing import StandardScaler

MAX_DRIVERS = 5

def design(feats):
    # Remove near-duplicates based on correlation
    corr_threshold = 0.6
    corr_matrix = np.corrcoef(feats.x.T)
    to_remove = set()
    for i in range(len(feats.ids)):
        for j in range(i+1, len(feats.ids)):
            if abs(corr_matrix[i,j]) >= corr_threshold:
                to_remove.add(feats.ids[j])

    usable_ids = [fid for fid in feats.ids if fid not in to_remove]

    # Handle case where no features remain after duplicate removal
    if not usable_ids:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Get indices for usable features
    usable_indices = [feats.column(fid) for fid in usable_ids]

    # Calculate effect sizes and select top candidates
    x_subset = feats.x[:, usable_indices]
    effect_sizes = []
    for i, fid in enumerate(usable_ids):
        group_means = [np.mean(x_subset[feats.y==c, i]) for c in [0,1]]
        effect_size = group_means[1] - group_means[0]
        effect_sizes.append((fid, abs(effect_size)))

    # Sort by absolute effect size
    effect_sizes.sort(key=lambda x: x[1], reverse=True)

    # Select top features as potential drivers
    candidate_drivers = [fid for fid, _ in effect_sizes[:MAX_DRIVERS]]

    # Check for strong correlations among top features
    if len(candidate_drivers) > 1:
        # Get indices for candidate drivers
        driver_indices = [feats.column(fid) for fid in candidate_drivers if fid in feats.ids]
        if len(driver_indices) > 1:
            selected_corr = np.corrcoef(x_subset[:, driver_indices].T)
            # Remove correlated features
            to_remove_drivers = set()
            for i in range(len(candidate_drivers)):
                for j in range(i+1, len(candidate_drivers)):
                    if j < len(selected_corr) and i < len(selected_corr):
                        if abs(selected_corr[i,j]) >= 0.6:
                            to_remove_drivers.add(candidate_drivers[j])

            candidate_drivers = [fid for fid in candidate_drivers if fid not in to_remove_drivers]

    # If no strong effect, return empty design
    if len(candidate_drivers) == 0:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Build regression components
    drivers = tuple(candidate_drivers)
    columns = tuple(usable_ids)

    # Add interaction terms between top drivers
    products = []
    for i in range(len(drivers)):
        for j in range(i+1, len(drivers)):
            products.append((drivers[i], drivers[j]))

    # Weighted score using effect sizes
    loadings = {}
    for i, fid in enumerate(usable_ids):
        if fid in candidate_drivers:
            group_means = [np.mean(x_subset[feats.y==c, i]) for c in [0,1]]
            loadings[fid] = group_means[1] - group_means[0]

    return Design(drivers=drivers, columns=columns, products=tuple(products), loadings=loadings)
